import { FilterDataAccessor, FilterRegistry } from 'domain/Filter';
import type {
  FilterDataStructure,
  FilterForm,
  FilterValue,
} from 'models/Filters';

import {
  getSubBrands,
  hasSingleSubBrand,
  hasSpecificValue,
} from './utils/resolveCommercialResultsWaterfallOptions';

/**
 * When a brand with only one sub-brand is selected and sub_brands is not yet
 * specific, auto-selects that sub-brand.
 *
 * Must be called ONLY after the brand-scoped preset (tier 3) has arrived —
 * i.e. from refreshCommercialResultsFilterData.fulfilled.
 *
 */
export function autoSelectSingleSubBrandAfterPresetRefresh(
  dataFilters: FilterDataStructure,
  form: FilterForm,
): FilterForm {
  if (
    !hasSpecificValue(form.brands) ||
    hasSpecificValue(form.sub_brands) ||
    !hasSingleSubBrand(dataFilters, form.brands)
  ) {
    return form;
  }

  const singleSubBrand = getSubBrands(dataFilters)[0]?.value ?? 'All';
  return { ...form, sub_brands: singleSubBrand };
}

/** Dimensions scoped by selected brand on Commercial Results only. */
export const COMMERCIAL_BRAND_DEPENDENT_DIMENSION_KEYS = [
  'region',
  'channel',
  'pack_type',
] as const;

export type CommercialBrandDependentDimensionKey =
  (typeof COMMERCIAL_BRAND_DEPENDENT_DIMENSION_KEYS)[number];

const isBaselineAll = (value: FilterValue | undefined): boolean => {
  if (value == null || value === '') return true;
  return String(value).toUpperCase() === 'ALL';
};

const getDefaultForDimension = (
  dataFilters: FilterDataStructure,
  key: CommercialBrandDependentDimensionKey,
): FilterValue | null => {
  const block = dataFilters[key];
  return block?.default?.value ?? null;
};

const isValueValidForDimension = (
  dataFilters: FilterDataStructure,
  form: FilterForm,
  key: CommercialBrandDependentDimensionKey,
  value: FilterValue | undefined,
): boolean => {
  if (isBaselineAll(value)) return true;

  const options = FilterDataAccessor.getInstance().getOptions(
    key,
    dataFilters,
    form,
  );

  if (!options.length) return false;

  return options.some((option) => String(option.value) === String(value));
};

const getSubBrandBaseline = (dataFilters: FilterDataStructure): FilterValue =>
  dataFilters.sub_brands?.default?.value ?? 'All';

const isSubBrandValidForBrand = (
  dataFilters: FilterDataStructure,
  form: FilterForm,
): boolean => {
  const subBrand = form.sub_brands;
  if (isBaselineAll(subBrand)) return true;

  const contextualValidator =
    FilterRegistry.getInstance().getContextualValidator('sub_brands');
  if (!contextualValidator) return true;

  return contextualValidator(
    dataFilters,
    String(form.brands ?? ''),
    String(subBrand),
  );
};

const isBrandValidForScopedPreset = (
  dataFilters: FilterDataStructure,
  form: FilterForm,
): boolean => {
  if (isBaselineAll(form.brands)) return true;

  const options = FilterDataAccessor.getInstance().getOptions(
    'brands',
    dataFilters,
    form,
  );

  if (!options.length) return false;

  return options.some((option) => String(option.value) === String(form.brands));
};

const resetBrandHierarchyToBaseline = (
  dataFilters: FilterDataStructure,
  form: FilterForm,
): FilterForm => ({
  ...form,
  brands: dataFilters.brands?.default?.value ?? 'All',
  sub_brands: dataFilters.sub_brands?.default?.value ?? 'All',
  sku: dataFilters.sku?.default?.value ?? null,
});

/**
 * Resets region/channel/pack_type to preset baseline when the current value
 * is not in the option list (e.g. after brand-scoped preset refresh).
 * Also resets sku to 'All' when any parent dimension changed.
 *
 * Does NOT auto-select sub_brand — use autoSelectSingleSubBrandAfterPresetRefresh
 * for that, exclusively after the brand-scoped preset arrives.
 */
export function reconcileCommercialBrandDependentDimensions(
  dataFilters: FilterDataStructure,
  form: FilterForm,
  prevApplied?: FilterForm,
): FilterForm {
  const next: FilterForm = { ...form };

  for (const key of COMMERCIAL_BRAND_DEPENDENT_DIMENSION_KEYS) {
    const current = next[key];
    if (isValueValidForDimension(dataFilters, next, key, current)) {
      continue;
    }
    next[key] = getDefaultForDimension(dataFilters, key);
  }

  if (!isSubBrandValidForBrand(dataFilters, next)) {
    next.sub_brands = getSubBrandBaseline(dataFilters);
    next.sku = dataFilters.sku?.default?.value ?? 'All';
  }

  if (prevApplied && hasSpecificValue(next.sku)) {
    const parentChanged =
      prevApplied.brands !== next.brands ||
      prevApplied.sub_brands !== next.sub_brands ||
      prevApplied.region !== next.region ||
      prevApplied.channel !== next.channel ||
      prevApplied.pack_type !== next.pack_type ||
      prevApplied.periods !== next.periods;

    if (parentChanged) {
      next.sku = 'All';
    }
  }

  return next;
}

/**
 * Bidirectional reconciliation on Apply:
 * 1. Invalid brand for active flat drivers → reset brand hierarchy, keep flat filters.
 * 2. Invalid flat filters for brand → reset flat filters to baseline.
 */
export function reconcileCommercialResultsForm(
  dataFilters: FilterDataStructure,
  form: FilterForm,
): FilterForm {
  if (!isBrandValidForScopedPreset(dataFilters, form)) {
    return resetBrandHierarchyToBaseline(dataFilters, form);
  }

  return reconcileCommercialBrandDependentDimensions(dataFilters, form);
}

/**
 * Clears brand-dependent dimensions when the user picks a different brand
 * in the Commercial Results drawer (before Apply).
 */
export function cascadeCommercialBrandDependentDimensionsToBaseline(
  dataFilters: FilterDataStructure,
  form: FilterForm,
): FilterForm {
  const next: FilterForm = { ...form };

  for (const key of COMMERCIAL_BRAND_DEPENDENT_DIMENSION_KEYS) {
    next[key] = getDefaultForDimension(dataFilters, key) ?? 'All';
  }

  return next;
}
